const envelope = $json.body && typeof $json.body === 'object' ? $json.body : $json;
const headers = $json.headers && typeof $json.headers === 'object' ? $json.headers : {};
const suppliedSecret = String(headers['x-handoff-key'] || headers['X-Handoff-Key'] || '');
const expectedSecret = String($env.CORTEX_04_HANDOFF_SECRET || '');
if (!expectedSecret) throw new Error('Configuration absente : renseignez CORTEX_04_HANDOFF_SECRET dans n8n.');
if (!suppliedSecret || suppliedSecret !== expectedSecret) throw new Error('Accès refusé : clé de handoff invalide.');
const reference = String(envelope.reference || '').trim().toUpperCase();
if (!/^MIS-2026-\d{4}$/.test(reference)) throw new Error('Référence de mission absente ou invalide : format attendu MIS-2026-XXXX.');
const expediteur = String(envelope.expediteur || '').replace(/\D/g, '');
if (!/^\d{7,15}$/.test(expediteur)) throw new Error('Numéro WhatsApp expéditeur absent ou invalide.');
const message = String(envelope.message || '').trim();
if (!message) throw new Error('Message brut du client absent.');
if (message.length > 4096) throw new Error('Le message client dépasse la taille maximale autorisée de 4096 caractères.');
const escapeHtml = value => String(value).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/\"/g, '&quot;').replace(/'/g, '&#39;');
const messageHtml = escapeHtml(message).replace(/\r?\n/g, '<br>');
return { json: { expediteur, message, message_html: messageHtml, reference } };

const response = $json;
const reference = $('Valider Handoff Option B').first().json.reference;
const candidates = [response, response.data].filter(value => value && typeof value === 'object');
let records = [];
for (const candidate of candidates) {
  for (const key of ['records', 'list', 'data']) {
    if (Array.isArray(candidate[key])) { records = candidate[key]; break; }
  }
  if (records.length) break;
}
if (Array.isArray(response)) records = response;
const normalized = records.map(record => record && record.fields && typeof record.fields === 'object' ? { ...record, ...record.fields } : record);
const matches = normalized.filter(record => String(record?.Code_Mission || '').trim().toUpperCase() === reference);
if (matches.length !== 1) throw new Error('La mission ' + reference + ' doit correspondre à exactement un enregistrement NocoDB ; résultats : ' + matches.length + '.');
const recordId = matches[0].Id ?? matches[0].id;
if (recordId === undefined || recordId === null || recordId === '') throw new Error('Identifiant primaire absent de l’enregistrement NocoDB pour ' + reference + '.');
return { json: { reference, record_id: recordId } };

const reference = String($json.query?.reference || '').trim().toUpperCase();
if (!/^MIS-2026-\d{4}$/.test(reference)) throw new Error('Référence de mission absente ou invalide : format attendu MIS-2026-XXXX.');
return { json: { reference } };

const response = $json;
const reference = $('Valider Référence Statut').first().json.reference;
const candidates = [response, response.data].filter(value => value && typeof value === 'object');
let records = [];
for (const candidate of candidates) {
  for (const key of ['records', 'list', 'data']) {
    if (Array.isArray(candidate[key])) { records = candidate[key]; break; }
  }
  if (records.length) break;
}
if (Array.isArray(response)) records = response;
const normalized = records.map(record => record && record.fields && typeof record.fields === 'object' ? { ...record, ...record.fields } : record);
const mission = normalized.find(record => String(record?.Code_Mission || '').trim().toUpperCase() === reference);
return { json: { reference, found: Boolean(mission), statut: mission ? String(mission.Statut || '') : '' } };
